"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Link from 'next/link';
import { BLOGS } from '../constants';
import { ArrowRight, User, Search } from 'lucide-react';
import useSEO from '../hooks/useSEO';

// Animated Typewriter Component for Blog Page
const TypewriterText: React.FC = React.memo(() => {
  const words = ["Industry Insights.", "Expert Knowledge.", "Tech Trends.", "Best Practices.", "Innovation Stories."];
  const [index, setIndex] = useState(0);
  const [subIndex, setSubIndex] = useState(0);
  const [reverse, setReverse] = useState(false);

  React.useEffect(() => {
    if (subIndex === words[index].length + 1 && !reverse) {
      setTimeout(() => setReverse(true), 1500);
      return;
    }

    if (subIndex === 0 && reverse) {
      setReverse(false);
      setIndex((prev) => (prev + 1) % words.length);
      return;
    }

    const timeout = setTimeout(() => {
      setSubIndex((prev) => prev + (reverse ? -1 : 1));
    }, reverse ? 40 : 80);

    return () => clearTimeout(timeout);
  }, [subIndex, index, reverse]);

  return (
    <span className="relative inline-block text-blue-400">
      {words[index].substring(0, subIndex)}
      <span className="inline-block w-[3px] h-[0.9em] bg-blue-400 ml-1 animate-pulse align-middle" />
    </span>
  );
});

const Blog: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  const categories = ['All', ...new Set(BLOGS.map(blog => blog.category))];

  const filteredBlogs = BLOGS.filter(blog => {
    const matchesSearch = blog.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      blog.excerpt.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || blog.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  // Format date to match the design
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const day = date.getDate().toString().padStart(2, '0');
    const month = date.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();
    return { day, month };
  };

  return (
    <div className="bg-white font-light selection:bg-blue-100 selection:text-blue-700 overflow-hidden">

      {/* Force solid navbar */}
      <style>{`
        nav .container > div {
          background: rgba(255, 255, 255, 0.95) !important;
          backdrop-filter: blur(12px) !important;
          box-shadow: 0 20px 60px rgba(0, 0, 0, 0.08) !important;
          border: 1px solid rgba(226, 232, 240, 1) !important;
        }
      `}</style>

      {/* HERO BANNER SECTION */}
      <section className="relative min-h-[70vh] md:h-[80vh] flex items-center justify-center overflow-hidden pt-32 md:pt-24">
        {/* Background Image */}
        <div
          className="absolute inset-0 bg-no-repeat"
          style={{ backgroundImage: 'url("/images/cover-image.jpg")', backgroundSize: '100% auto', backgroundPosition: 'center center' }}
        >
          {/* Gradient Black Overlay */}
          <div className="absolute inset-0 bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-800/85" />

          {/* Animated Grid Pattern */}
          <div className="absolute inset-0 opacity-5">
            <div className="absolute inset-0" style={{
              backgroundImage: 'linear-gradient(rgba(59, 130, 246, 0.2) 1px, transparent 1px), linear-gradient(90deg, rgba(59, 130, 246, 0.2) 1px, transparent 1px)',
              backgroundSize: '50px 50px'
            }} />
          </div>
        </div>

        {/* Content Container */}
        <div className="relative z-10 container mx-auto px-6 text-center">
          {/* Animated Badge */}
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            className="inline-flex items-center space-x-2 px-4 py-2 bg-blue-500/20 backdrop-blur-md border border-blue-400/30 rounded-full mb-6"
          >
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-pulse" />
            <span className="text-white/95 text-xs font-medium uppercase tracking-wider">QIntellect Blog</span>
          </motion.div>

          {/* Main Title with Animation */}
          <motion.h1
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="text-5xl md:text-7xl lg:text-8xl font-bold text-white mb-6 font-heading"
          >
            Our <span className="text-blue-400">Insights</span>
          </motion.h1>

          {/* Animated Description with Typewriter */}
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="text-xl md:text-2xl text-blue-100 mb-8 max-w-3xl mx-auto font-light"
          >
            Sharing <TypewriterText />
          </motion.div>

          {/* Additional Description */}
          <motion.p
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: 0.6 }}
            className="text-base md:text-lg text-slate-300 max-w-2xl mx-auto leading-relaxed mb-8 font-light"
          >
            Explore our latest thoughts on AI, technology trends, and enterprise solutions
            that drive digital transformation and business success.
          </motion.p>

          {/* Breadcrumb Navigation */}
          <motion.nav
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.8 }}
            className="flex items-center justify-center space-x-2 mb-12"
          >
            <Link
              href="/"
              className="text-slate-400 hover:text-white transition-colors duration-300 text-sm"
            >
              Home
            </Link>
            <ArrowRight className="w-4 h-4 text-slate-500" />
            <span className="text-blue-400 text-sm font-medium">Blog</span>
          </motion.nav>
        </div>
      </section>

      {/* BLOG CONTENT SECTION */}
      <div className="pt-16 pb-24 bg-gray-50">
        <div className="container mx-auto px-4 md:px-8">

          {/* Search and Filter Bar */}
          <div className="flex flex-col md:flex-row gap-6 mb-12 items-center justify-between">
            <div className="relative w-full md:w-96">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search articles..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            <div className="flex flex-wrap gap-2">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${selectedCategory === cat
                    ? 'bg-blue-600 text-white'
                    : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
                    }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* Blog Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <AnimatePresence mode='popLayout'>
              {filteredBlogs.map((post, i) => {
                const { day, month } = formatDate(post.date);
                return (
                  <motion.article
                    key={post.id}
                    layout
                    initial={{ opacity: 0, y: 30 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 30 }}
                    transition={{ duration: 0.5, delay: (i % 9) * 0.1 }}
                    className="group bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-1"
                  >
                    {/* Image Section */}
                    <div className="relative h-64 overflow-hidden">
                      <img loading="lazy"
                        src={post.image}
                        alt={post.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                      />
                      {/* Date Badge */}
                      <div className="absolute top-4 right-4 bg-blue-600 text-white px-3 py-2 rounded-lg text-center shadow-lg">
                        <div className="text-lg font-bold leading-none">{day}</div>
                        <div className="text-xs font-medium leading-none mt-1">{month}</div>
                      </div>
                    </div>

                    {/* Content Section */}
                    <div className="p-6">
                      {/* Author and Category */}
                      <div className="flex items-center gap-4 mb-4 text-sm">
                        <div className="flex items-center gap-2 text-gray-500">
                          <User className="w-4 h-4" />
                          <span>By {post.author}</span>
                        </div>
                        <span className="px-2 py-1 bg-blue-100 text-blue-600 rounded-full text-xs font-medium">
                          {post.category.split(' ')[0]}
                        </span>
                      </div>

                      {/* Title */}
                      <h3 className="text-xl font-bold text-gray-900 mb-3 group-hover:text-blue-600 transition-colors line-clamp-2">
                        {post.title}
                      </h3>

                      {/* Excerpt */}
                      <p className="text-gray-600 text-sm leading-relaxed mb-6 line-clamp-3">
                        {post.excerpt}
                      </p>

                      {/* Footer */}
                      <div className="flex items-center">
                        <Link
                          href={`/blog/${post.id}`}
                          className="inline-flex items-center gap-2 text-blue-600 font-medium text-sm hover:text-blue-700 transition-colors"
                        >
                          READ MORE
                          <ArrowRight className="w-4 h-4" />
                        </Link>
                      </div>
                    </div>
                  </motion.article>
                );
              })}
            </AnimatePresence>
          </div>

          {/* No Results */}
          {filteredBlogs.length === 0 && (
            <div className="text-center py-16">
              <div className="text-gray-400 mb-4">
                <Search className="w-16 h-16 mx-auto mb-4" />
                <h3 className="text-xl font-semibold mb-2">No articles found</h3>
                <p className="text-gray-500">Try adjusting your search terms or filters.</p>
              </div>
              <button
                onClick={() => { setSearchTerm(''); setSelectedCategory('All'); }}
                className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                Reset Filters
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Blog;

"use client";

import React, { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { BLOGS } from '../constants';
import {
  Calendar,
  User,
  Clock,
  ArrowLeft,
  Share2,
  ChevronRight,
  Tag,
  Mail,
  TrendingUp,
  ArrowRight,
  Bookmark,
  Eye,
  MessageSquare,
  Globe as Facebook,
  MessageCircle as Twitter,
  Briefcase as Linkedin,
  Search,
  Star
} from 'lucide-react';
const BlogDetail: React.FC = () => {
  const params = useParams();
  const id = params?.id as string;
  const post = BLOGS.find(p => p.id === id);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  if (!post) {
    return (
      <div className="min-h-screen flex items-center justify-center pt-32 text-center bg-gray-50">
        <div className="space-y-6">
          <h2 className="text-3xl font-bold text-gray-900">Blog Post Not Found</h2>
          <p className="text-gray-600">The blog post you're looking for doesn't exist.</p>
          <Link href="/blog" className="inline-block px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
            Back to Blog
          </Link>
        </div>
      </div>
    );
  }

  // Get related posts from the same category
  const relatedPosts = BLOGS.filter(p => p.id !== post.id && p.category === post.category).slice(0, 3);
  // Get recent posts if not enough related posts
  const recentPosts = BLOGS.filter(p => p.id !== post.id).slice(0, 6);
  const sidebarPosts = relatedPosts.length >= 3 ? relatedPosts : recentPosts;

  // Format date
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  return (
    <div className="bg-white min-h-screen">

      {/* Breadcrumb */}
      <div className="bg-gray-50 pt-32 pb-8">
        <div className="container mx-auto px-4 md:px-8">
          <nav className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-gray-600">
            <Link href="/" className="hover:text-blue-600 transition-colors">Home</Link>
            <ChevronRight className="w-4 h-4 flex-shrink-0" />
            <Link href="/blog" className="hover:text-blue-600 transition-colors">Blog</Link>
            <ChevronRight className="w-4 h-4 flex-shrink-0" />
            <span className="text-blue-600 font-medium">{post.category}</span>
          </nav>
        </div>
      </div>

      <div className="container mx-auto px-4 md:px-8 py-12">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">

          {/* Main Content */}
          <div className="lg:col-span-3">
            <article className="bg-white">

              {/* Article Header */}
              <header className="mb-8">
                <div className="mb-4">
                  <span className="inline-block px-3 py-1 bg-blue-100 text-blue-600 text-sm font-medium rounded-full">
                    {post.category}
                  </span>
                </div>

                <h1 className="text-4xl md:text-5xl font-bold text-gray-900 mb-6 leading-tight">
                  {post.title}
                </h1>

                <div className="flex items-center gap-6 text-sm text-gray-600 mb-6">
                  <div className="flex items-center gap-2">
                    <User className="w-4 h-4" />
                    <span>By {post.author}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4" />
                    <span>{formatDate(post.date)}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4" />
                    <span>{post.readTime}</span>
                  </div>
                </div>

                <p className="text-xl text-gray-600 leading-relaxed mb-8 font-light">
                  {post.excerpt}
                </p>
              </header>

              {/* Featured Image */}
              <div className="mb-12">
                <img loading="lazy"
                  src={post.image}
                  alt={post.title}
                  className="w-full h-96 object-cover rounded-2xl shadow-lg"
                />
              </div>

              {/* Article Content */}
              <div className="prose prose-lg max-w-none mb-12">
                {post.sections.map((section, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ delay: index * 0.1 }}
                    className="mb-8"
                  >
                    {section.heading && (
                      <h2 className="text-3xl font-bold text-gray-900 mb-6 border-l-4 border-blue-600 pl-6">
                        {section.heading}
                      </h2>
                    )}
                    <div className="space-y-4">
                      {section.content.map((paragraph, pIndex) => (
                        <p key={pIndex} className="text-lg text-gray-700 leading-relaxed">
                          {paragraph}
                        </p>
                      ))}
                    </div>
                  </motion.div>
                ))}

                {/* Additional Content Sections */}
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  className="mb-8"
                >
                  <h2 className="text-3xl font-bold text-gray-900 mb-6 border-l-4 border-blue-600 pl-6">
                    Implementation Best Practices
                  </h2>
                  <div className="space-y-4">
                    <p className="text-lg text-gray-700 leading-relaxed">
                      When implementing these solutions, it's crucial to follow industry best practices and maintain security standards throughout the development process. Our team has compiled comprehensive guidelines based on years of enterprise experience.
                    </p>
                    <ul className="list-disc list-inside space-y-2 text-lg text-gray-700 ml-4">
                      <li>Conduct thorough security assessments before deployment</li>
                      <li>Implement comprehensive testing protocols for all integrations</li>
                      <li>Establish monitoring and logging systems for operational visibility</li>
                      <li>Create detailed documentation for future maintenance</li>
                      <li>Plan for scalability and performance optimization</li>
                    </ul>
                  </div>
                </motion.div>

                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  className="mb-8"
                >
                  <h2 className="text-3xl font-bold text-gray-900 mb-6 border-l-4 border-blue-600 pl-6">
                    Future Considerations
                  </h2>
                  <div className="space-y-4">
                    <p className="text-lg text-gray-700 leading-relaxed">
                      As technology continues to evolve, it's important to stay ahead of emerging trends and prepare your systems for future enhancements. Consider these forward-looking strategies:
                    </p>
                    <p className="text-lg text-gray-700 leading-relaxed">
                      Integration with artificial intelligence and machine learning capabilities will become increasingly important. Organizations should plan for API flexibility and data structure adaptability to accommodate future AI enhancements.
                    </p>
                  </div>
                </motion.div>
              </div>

              {/* Gallery Images */}
              {post.galleryImages && post.galleryImages.length > 0 && (
                <div className="mb-12">
                  <h3 className="text-2xl font-bold text-gray-900 mb-6">Related Images</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {post.galleryImages.map((image, index) => (
                      <div key={index} className="rounded-xl overflow-hidden shadow-lg">
                        <img loading="lazy"
                          src={image}
                          alt={`Gallery image ${index + 1}`}
                          className="w-full h-64 object-cover hover:scale-105 transition-transform duration-300"
                        />
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Technical Specs */}
              {post.technicalSpecs && post.technicalSpecs.length > 0 && (
                <div className="bg-gray-50 rounded-xl p-8 mb-12">
                  <h3 className="text-2xl font-bold text-gray-900 mb-6">Technical Specifications</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {post.technicalSpecs.map((spec, index) => (
                      <div key={index} className="flex justify-between items-center p-4 bg-white rounded-lg border">
                        <span className="font-medium text-gray-700">{spec.label}</span>
                        <span className="text-blue-600 font-semibold">{spec.value}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Tags */}
              <div className="mb-12">
                <h3 className="text-xl font-semibold text-gray-900 mb-4">Tags</h3>
                <div className="flex flex-wrap gap-2">
                  {post.tags.map(tag => (
                    <span
                      key={tag}
                      className="px-3 py-1 bg-gray-100 text-gray-700 rounded-full text-sm hover:bg-blue-100 hover:text-blue-600 transition-colors cursor-pointer"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* Author Info */}
              <div className="bg-gradient-to-r from-blue-50 to-indigo-50 rounded-2xl p-8 mb-12">
                <div className="flex items-start gap-6">
                  <img loading="lazy"
                    src={post.authorImage}
                    alt={post.author}
                    className="w-20 h-20 rounded-full object-cover ring-4 ring-white shadow-lg"
                  />
                  <div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">{post.author}</h3>
                    <p className="text-blue-600 font-medium mb-3">{post.authorRole}</p>
                    <p className="text-gray-600 leading-relaxed">
                      {post.author} is a seasoned expert in {post.category.toLowerCase()} with extensive experience in enterprise solutions and digital transformation.
                      They regularly contribute insights on cutting-edge technologies and industry best practices.
                    </p>
                  </div>
                </div>
              </div>

              {/* Share Buttons */}
              <div className="border-t border-gray-200 pt-8">
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                  <h3 className="text-lg font-semibold text-gray-900">Share this article</h3>
                  <div className="flex flex-wrap items-center gap-4">
                    <button
                      onClick={() => window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`, '_blank')}
                      className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                    >
                      <Facebook className="w-4 h-4" />
                      <span>Facebook</span>
                    </button>
                    <button
                      onClick={() => window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(window.location.href)}`, '_blank')}
                      className="flex items-center gap-2 px-4 py-2 bg-blue-700 text-white rounded-lg hover:bg-blue-800 transition-colors"
                    >
                      <Linkedin className="w-4 h-4" />
                      <span>LinkedIn</span>
                    </button>
                  </div>
                </div>
              </div>

            </article>
          </div>

          {/* Sidebar */}
          <div className="lg:col-span-1">
            <div className="sticky top-8 space-y-8">

              {/* Author Card */}
              <div className="bg-white rounded-xl p-6">
                <div className="text-center">
                  <img loading="lazy"
                    src={post.authorImage}
                    alt={post.author}
                    className="w-16 h-16 rounded-full mx-auto mb-4 object-cover"
                  />
                  <h3 className="font-semibold text-gray-900 mb-1">{post.author}</h3>
                  <p className="text-sm text-blue-600 mb-3">{post.authorRole}</p>
                  <p className="text-sm text-gray-600 leading-relaxed">
                    Expert in {post.category.toLowerCase()} with extensive experience.
                  </p>
                </div>
              </div>

              {/* Recent/Related Posts */}
              <div className="bg-white rounded-xl p-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-6 flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-blue-600" />
                  {relatedPosts.length >= 3 ? 'Related Articles' : 'Recent Articles'}
                </h3>
                <div className="space-y-4">
                  {sidebarPosts.slice(0, 4).map(relatedPost => (
                    <Link
                      key={relatedPost.id}
                      href={`/blog/${relatedPost.id}`}
                      className="group block hover:bg-gray-50 rounded-lg p-3 transition-colors -mx-3"
                    >
                      <div className="flex gap-3">
                        <img loading="lazy"
                          src={relatedPost.image}
                          alt={relatedPost.title}
                          className="w-16 h-16 object-cover rounded-lg flex-shrink-0"
                        />
                        <div>
                          <h4 className="font-medium text-gray-900 group-hover:text-blue-600 transition-colors line-clamp-2 text-sm leading-tight mb-1">
                            {relatedPost.title}
                          </h4>
                          <p className="text-xs text-gray-500">{relatedPost.readTime}</p>
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
                <div className="mt-6 pt-6 border-t">
                  <Link
                    href="/blog"
                    className="flex items-center justify-center gap-2 w-full py-2 text-blue-600 hover:text-blue-700 transition-colors font-medium text-sm"
                  >
                    View All Articles
                    <ArrowRight className="w-4 h-4" />
                  </Link>
                </div>
              </div>

              {/* Newsletter Signup */}
              <div className="bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl p-6 text-white">
                <div className="text-center">
                  <Mail className="w-8 h-8 mx-auto mb-4 opacity-90" />
                  <h3 className="text-xl font-bold mb-2">Monthly Tech Digest</h3>
                  <p className="text-blue-100 text-sm mb-6 leading-relaxed">
                    Join our newsletter to get a monthly roundup of our best insights on AI, ERP, and EDI solutions.
                  </p>
                  <form
                    onSubmit={async (e) => {
                      e.preventDefault();
                      const form = e.currentTarget;
                      const emailInput = form.elements.namedItem('email') as HTMLInputElement;
                      const submitBtn = form.elements.namedItem('submitBtn') as HTMLButtonElement;

                      try {
                        submitBtn.disabled = true;
                        submitBtn.textContent = 'Subscribing...';

                        const res = await fetch('/api/subscribe', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({ email: emailInput.value }),
                        });

                        if (res.ok) {
                          alert("Thanks for subscribing to our Monthly Tech Digest!");
                          form.reset();
                        } else {
                          const data = await res.json();
                          alert(data.error || "An error occurred. Please try again.");
                        }
                      } catch (err) {
                        alert("An error occurred. Please try again.");
                      } finally {
                        submitBtn.disabled = false;
                        submitBtn.textContent = 'Subscribe Now';
                      }
                    }}
                    className="space-y-3"
                  >
                    <input
                      name="email"
                      type="email"
                      placeholder="Enter your email"
                      required
                      className="w-full px-4 py-3 bg-white rounded-lg text-gray-900 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-400 border-none"
                    />
                    <button name="submitBtn" type="submit" className="w-full py-3 bg-white text-blue-600 rounded-lg hover:bg-gray-50 transition-colors font-bold shadow-lg disabled:opacity-75">
                      Subscribe Now
                    </button>
                  </form>
                  <p className="text-xs text-blue-200 mt-4">We respect your privacy. Unsubscribe at any time.</p>
                </div>
              </div>

              {/* Popular Tags */}
              <div className="bg-white rounded-xl p-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Popular Tags</h3>
                <div className="flex flex-wrap gap-2">
