          </motion.div>

          <div className="grid lg:grid-cols-2 gap-12 items-center">
            {/* Left - Steps */}
            <div className="space-y-6">
              {[
                { step: '01', title: 'Tell Us Your Needs', desc: 'Share your ideas with us. We listen and understand.', icon: Target, image: 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=2070&auto=format&fit=crop' },
                { step: '02', title: 'We Make a Plan', desc: 'Our team creates a clear roadmap for you.', icon: Layers, image: 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=2070&auto=format&fit=crop' },
                { step: '03', title: 'Build & Test', desc: 'We build your solution and test it well.', icon: Code, image: 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?q=80&w=2072&auto=format&fit=crop' },
                { step: '04', title: 'Launch & Support', desc: 'Go live! We stay with you for support.', icon: Zap, image: 'https://images.unsplash.com/photo-1504639725590-34d0984388bd?q=80&w=2070&auto=format&fit=crop' }
              ].map((item, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, x: -30 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  transition={{ delay: i * 0.1 }}
                  viewport={{ once: true }}
                  onMouseEnter={() => setActiveStep(i)}
                  className={`group p-6 rounded-2xl border-2 transition-all duration-500 cursor-pointer ${activeStep === i
                    ? 'bg-blue-50 border-blue-500 shadow-xl'
                    : 'bg-white border-slate-100 hover:border-blue-200'
                    }`}
                >
                  <div className="flex items-start gap-5">
                    <div className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${activeStep === i
                      ? 'bg-blue-500 shadow-lg shadow-blue-500/30'
                      : 'bg-slate-100 group-hover:bg-blue-100'
                      }`}>
                      <item.icon className={`w-8 h-8 transition-colors ${activeStep === i ? 'text-white' : 'text-slate-600 group-hover:text-blue-600'}`} />
                    </div>
                    <div className="flex-1">
                      <div className={`text-sm font-bold mb-1 ${activeStep === i ? 'text-blue-500' : 'text-slate-400'}`}>
                        Step {item.step}
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 mb-2">{item.title}</h3>
                      <p className="text-slate-500">{item.desc}</p>
                    </div>
                    <motion.div
                      animate={{ scale: activeStep === i ? 1 : 0.8, opacity: activeStep === i ? 1 : 0.3 }}
                      className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center"
                    >
                      <ChevronRight className="w-5 h-5 text-white" />
                    </motion.div>
                  </div>
                </motion.div>
              ))}
            </div>

            {/* Right - Image */}
            <motion.div
              initial={{ opacity: 0, x: 30 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              className="relative"
            >
              <div className="relative rounded-3xl overflow-hidden shadow-2xl">
                <AnimatePresence mode="wait">
                  <motion.img
                    key={activeStep}
                    initial={{ opacity: 0, scale: 1.1 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.95 }}
                    transition={{ duration: 0.5 }}
                    src={[
                      'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=2070&auto=format&fit=crop',
                      'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=2070&auto=format&fit=crop',
                      'https://images.unsplash.com/photo-1498050108023-c5249f4df085?q=80&w=2072&auto=format&fit=crop',
                      'https://images.unsplash.com/photo-1504639725590-34d0984388bd?q=80&w=2070&auto=format&fit=crop'
                    ][activeStep]}
                    alt="Process Step"
                    className="w-full h-[500px] object-cover"
                  />
                </AnimatePresence>
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-transparent to-transparent" />

                {/* Step Indicator */}
                <div className="absolute bottom-6 left-6 right-6">
                  <div className="flex gap-2 mb-4">
                    {[0, 1, 2, 3].map((i) => (
                      <motion.div
                        key={i}
                        animate={{
                          width: activeStep === i ? 40 : 10,
                          backgroundColor: activeStep === i ? '#3b82f6' : '#ffffff50'
                        }}
                        className="h-2 rounded-full"
                      />
                    ))}
                  </div>
                  <motion.div
                    key={activeStep}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-white"
                  >
                    <p className="text-2xl font-bold">
                      {['Discovery', 'Planning', 'Development', 'Launch'][activeStep]}
                    </p>
                  </motion.div>
                </div>
              </div>

              {/* Floating Elements */}
              <motion.div
                animate={{ y: [0, -10, 0] }}
                transition={{ duration: 3, repeat: Infinity }}
                className="absolute -top-6 -right-6 w-20 h-20 bg-blue-500 rounded-2xl shadow-xl flex items-center justify-center"
              >
                <span className="text-2xl font-bold text-white">0{activeStep + 1}</span>
              </motion.div>
            </motion.div>
          </div>
        </section>

        {/* ===== INDUSTRIES WE SERVE ===== */}
        <section className="mb-32">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <span className="inline-block px-4 py-2 bg-blue-100 text-blue-600 text-xs font-bold uppercase tracking-wider rounded-full mb-6">
              Industries
            </span>
            <h2 className="text-4xl md:text-5xl font-bold text-slate-900 font-heading mb-6">
              Who We <span className="text-blue-600">Help</span>
            </h2>
            <p className="text-xl text-slate-500 max-w-2xl mx-auto">
              We work with many industries to bring smart solutions
            </p>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {[
              { name: 'Customer Care & Hospitality', slug: 'customer-care-hospitality', icon: Hotel, image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?q=80&w=2070&auto=format&fit=crop', desc: 'Guest management and booking systems' },
              { name: 'Healthcare', slug: 'healthcare', icon: Stethoscope, image: 'https://images.unsplash.com/photo-1607619056574-7b8d3ee536b2?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MjB8fGhlYWx0aGNhcmV8ZW58MHx8MHx8fDA%3D', desc: 'Smart systems for hospitals and clinics' },
              { name: 'Marketing', slug: 'marketing', icon: Megaphone, image: 'https://images.unsplash.com/photo-1608222351212-18fe0ec7b13b?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MTR8fG1hcmtldGluZ3xlbnwwfHwwfHx8MA%3D%3D', desc: 'Campaign management and CRM solutions' },
              { name: 'Finance & Banking', slug: 'finance-banking', icon: Banknote, image: 'https://images.unsplash.com/photo-1725258080098-727051947997?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mjd8fGZpbmFuY2UlMjBiYW5raW5nfGVufDB8fDB8fHww', desc: 'Secure financial systems and solutions' },
              { name: 'Manufacturing & Retail', slug: 'manufacturing-retail', icon: Factory, image: 'https://images.unsplash.com/photo-1496247749665-49cf5b1022e9?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8OHx8bWFudWZhY3R1cmluZ3xlbnwwfHwwfHx8MA%3D%3D', desc: 'Automation and e-commerce solutions' },
              { name: 'Logistics', slug: 'logistics', icon: Truck, image: 'https://images.unsplash.com/photo-1494412574643-ff11b0a5c1c3?q=80&w=2070&auto=format&fit=crop', desc: 'Tracking and delivery systems' },
              { name: 'Education', slug: 'education', icon: GraduationCap, image: 'https://images.unsplash.com/photo-1488190211105-8b0e65b80b4e?q=80&w=2070&auto=format&fit=crop', desc: 'Learning platforms and tools' },
              { name: 'Supply Chain', slug: 'supply-chain', icon: Package, image: 'https://images.unsplash.com/photo-1553413077-190dd305871c?q=80&w=2125&auto=format&fit=crop', desc: 'End-to-end supply chain optimization' },
              { name: 'Technology', slug: 'technology', icon: Laptop, image: 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Nnx8dGVjaG5vbG9neXxlbnwwfHwwfHx8MA%3D%3D', desc: 'Software development and IT solutions' },
              { name: 'Real Estate', slug: 'real-estate', icon: Home, image: 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?q=80&w=2073&auto=format&fit=crop', desc: 'Property management and sales platforms' }
            ].map((industry, i) => (
              <Link href={`/industries/${industry.slug}`} key={i}>
                <motion.div
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.1 }}
                  viewport={{ once: true }}
                  whileHover={{ y: -10 }}
                  className="group relative rounded-3xl overflow-hidden shadow-xl h-72 cursor-pointer"
                >
                  {/* Background Image */}
                  <img loading="lazy"
                    src={industry.image}
                    alt={industry.name}
                    className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                  />

                  {/* Overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/60 to-transparent group-hover:from-blue-900 group-hover:via-blue-900/60 transition-all duration-500" />

                  {/* Content */}
                  <div className="absolute inset-0 p-6 flex flex-col justify-end">
                    <motion.div
                      initial={{ scale: 1 }}
                      whileHover={{ scale: 1.1 }}
                      className="w-14 h-14 bg-white/20 backdrop-blur-sm rounded-xl flex items-center justify-center mb-4 group-hover:bg-blue-500 transition-all"
                    >
                      <industry.icon className="w-7 h-7 text-white" />
                    </motion.div>
                    <h3 className="text-2xl font-bold text-white mb-2">{industry.name}</h3>
                    <p className="text-slate-300 text-sm opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
                      {industry.desc}
                    </p>
                  </div>

                  {/* Hover Arrow */}
                  <motion.div
                    initial={{ opacity: 0, x: -10 }}
                    whileHover={{ opacity: 1, x: 0 }}
                    className="absolute top-6 right-6 w-10 h-10 bg-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <ArrowUpRight className="w-5 h-5 text-slate-900" />
                  </motion.div>
                </motion.div>
              </Link>
            ))}
          </div>
        </section>

        {/* ===== CTA SECTION ===== */}
        <section className="mb-20">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="relative rounded-3xl overflow-hidden"
          >
            {/* Background */}
            <div className="absolute inset-0">
              <img loading="lazy"
                src="https://images.unsplash.com/photo-1497366216548-37526070297c?q=80&w=2069&auto=format&fit=crop"
                alt="Office"
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-br from-slate-900/95 via-blue-900/90 to-slate-900/95" />
            </div>

            {/* Animated Elements */}
            <motion.div
              animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
              transition={{ duration: 5, repeat: Infinity }}
              className="absolute top-10 right-10 w-64 h-64 bg-blue-500/20 rounded-full blur-3xl"
            />
            <motion.div
              animate={{ scale: [1.2, 1, 1.2], opacity: [0.2, 0.4, 0.2] }}
              transition={{ duration: 7, repeat: Infinity }}
              className="absolute bottom-10 left-10 w-48 h-48 bg-purple-500/20 rounded-full blur-3xl"
            />

            <div className="relative z-10 p-12 md:p-20">
              <div className="max-w-3xl mx-auto text-center">
                <motion.div
                  initial={{ opacity: 0, scale: 0 }}
                  whileInView={{ opacity: 1, scale: 1 }}
                  viewport={{ once: true }}
                  className="w-20 h-20 bg-blue-500 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl shadow-blue-500/30"
                >
                  <Rocket className="w-10 h-10 text-white" />
                </motion.div>

                <motion.h2
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  className="text-4xl md:text-6xl font-bold text-white font-heading mb-6"
                >
                  Ready to Start?
                </motion.h2>
                <motion.p
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.1 }}
                  viewport={{ once: true }}
                  className="text-xl text-slate-300 mb-10"
                >
                  Let&apos;s build something amazing together. Talk to us today!
                </motion.p>
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 }}
                  viewport={{ once: true }}
                  className="flex flex-wrap justify-center gap-4"
                >
                  <Link href="/contact" className="group inline-flex items-center gap-3 px-10 py-5 bg-blue-500 text-white rounded-full font-bold hover:bg-blue-400 transition-all shadow-lg shadow-blue-500/30 hover:shadow-xl hover:-translate-y-1 text-lg">
                    Get Free Quote
                    <motion.div animate={{ x: [0, 5, 0] }} transition={{ duration: 1.5, repeat: Infinity }}>
                      <ArrowRight className="w-6 h-6" />
                    </motion.div>
                  </Link>
                  <Link href="/portfolios" className="inline-flex items-center gap-3 px-10 py-5 bg-white/10 backdrop-blur-sm text-white rounded-full font-bold border-2 border-white/30 hover:bg-white/20 hover:border-white transition-all hover:-translate-y-1 text-lg">
                    <Play className="w-6 h-6" />
                    See Our Work
                  </Link>
                </motion.div>

                {/* Trust Badges */}
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3 }}
                  viewport={{ once: true }}
                  className="flex flex-wrap justify-center gap-8 mt-12 pt-12 border-t border-white/10"
                >
                  {[
                    { icon: Shield, text: 'Secure' },
                    { icon: Clock, text: 'Fast' },
                    { icon: Award, text: 'Quality' },
                    { icon: Heart, text: 'Care' }
                  ].map((item, i) => (
                    <div key={i} className="flex items-center gap-2 text-white/80">
                      <item.icon className="w-5 h-5" />
                      <span className="font-semibold">{item.text}</span>
                    </div>
                  ))}
                </motion.div>
              </div>
            </div>
          </motion.div>
        </section>
      </div>
    </div>
  );
};

export default Services;
